-- Recovery verification: this must show exactly 5 rows and every
-- has_marking_scheme value must be true.
SELECT
  e.id,
  g.name AS grade,
  s.name AS subject,
  e.exam_type,
  e.marks,
  e.status,
  (ms.id IS NOT NULL) AS has_marking_scheme
FROM public.exams e
JOIN public.grades g ON g.id = e.grade_id
JOIN public.subjects s ON s.id = e.subject_id
LEFT JOIN public.marking_schemes ms ON ms.exam_id = e.id
WHERE e.id IN ('d3e8b126-1b85-4425-b031-74e0737e32c2'::uuid, '6badc832-82b4-4372-8c29-54b7ddb156c3'::uuid, 'dc9dc46e-fa60-4f81-bef8-8c7ec677a5cc'::uuid, 'dbec7951-0e8c-413f-9cf2-df94c640912f'::uuid, '85ed5bd4-9e2f-4ab3-a016-b20a5c9873b7'::uuid)
ORDER BY e.created_at;
